insert into "psychological_state_signals" ("signal_id", "created_at", "example_phrases", "is_active", "observable_indicator", "protocol_adjustment", "score_per_instance", "signal_type", "source_document", "state_code", "state_name", "trigger_threshold") values ('1', '2026-07-26 05:12:17.653652+00', '''We need to move fast,'' ''There is no time,'' ''Just tell me what to do''', 'true', 'Phrases indicating rush, pressure, no time', 'Slow the pace. Acknowledge time pressure before continuing. Use one question only.', '2', 'Speed / urgency language', 'Psychological State Scoring Table — Acute State Detection', 'A', 'Stress / Hyperactivation', '6 points in one response') on conflict do nothing;
insert into "psychological_state_signals" ("signal_id", "created_at", "example_phrases", "is_active", "observable_indicator", "protocol_adjustment", "score_per_instance", "signal_type", "source_document", "state_code", "state_name", "trigger_threshold") values ('2', '2026-07-26 05:12:17.653652+00', '''This will definitely work,'' ''That is impossible,'' ''We can never recover''', 'true', 'Always / never / impossible / definitely in uncertain contexts', 'Gently test the absolute. ''When you say never — has there been a time where something similar has worked?''', '2', 'Absolutist language', 'Psychological State Scoring Table — Acute State Detection', 'A', 'Stress / Hyperactivation', '4 points across 3 responses') on conflict do nothing;
insert into "psychological_state_signals" ("signal_id", "created_at", "example_phrases", "is_active", "observable_indicator", "protocol_adjustment", "score_per_instance", "signal_type", "source_document", "state_code", "state_name", "trigger_threshold") values ('3', '2026-07-26 05:12:17.653652+00', 'Starts answering Q about sales, pivots to team conflict, pivots to funding unprompted', 'true', 'Answers jump between unrelated topics without resolution', 'Anchor the founder back. ''Let us stay with the sales question for a moment — you mentioned...''', '3', 'Topic jumping / fragmentation', 'Psychological State Scoring Table — Acute State Detection', 'A', 'Stress / Hyperactivation', '3 points in one response') on conflict do nothing;
insert into "psychological_state_signals" ("signal_id", "created_at", "example_phrases", "is_active", "observable_indicator", "protocol_adjustment", "score_per_instance", "signal_type", "source_document", "state_code", "state_name", "trigger_threshold") values ('4', '2026-07-26 05:12:17.653652+00', '3+ paragraphs of background before stating the actual problem', 'true', 'Over-explains context without reaching a point', 'Summarise what has been said and ask a direct closed question to anchor.', '2', 'Excessive detail with no conclusion', 'Psychological State Scoring Table — Acute State Detection', 'A', 'Stress / Hyperactivation', '6 points in session') on conflict do nothing;
insert into "psychological_state_signals" ("signal_id", "created_at", "example_phrases", "is_active", "observable_indicator", "protocol_adjustment", "score_per_instance", "signal_type", "source_document", "state_code", "state_name", "trigger_threshold") values ('5', '2026-07-26 05:12:17.653652+00', '''If this fails my family loses everything,'' ''I am out of options''', 'true', 'Sudden shift to extreme language about stakes', 'Pause. Acknowledge. ''That sounds like a really heavy weight to carry. Before we go further — how are you doing?''', '4', 'Rapid escalation language', 'Psychological State Scoring Table — Acute State Detection', 'A', 'Stress / Hyperactivation', '4 points (single instance)') on conflict do nothing;
insert into "psychological_state_signals" ("signal_id", "created_at", "example_phrases", "is_active", "observable_indicator", "protocol_adjustment", "score_per_instance", "signal_type", "source_document", "state_code", "state_name", "trigger_threshold") values ('6', '2026-07-26 05:12:17.653652+00', '''Fine.'' / ''Not sure.'' / ''It is okay.''', 'true', 'One word or one sentence answers to open questions', 'Normalise. ''It is completely okay to say you are not sure. What does it actually feel like right now?''', '2', 'Minimal responses', 'Psychological State Scoring Table — Acute State Detection', 'B', 'Withdrawal / Shutdown', '6 points across 3 responses') on conflict do nothing;
insert into "psychological_state_signals" ("signal_id", "created_at", "example_phrases", "is_active", "observable_indicator", "protocol_adjustment", "score_per_instance", "signal_type", "source_document", "state_code", "state_name", "trigger_threshold") values ('7', '2026-07-26 05:12:17.653652+00', '''Maybe,'' ''Perhaps,'' ''I think possibly,'' ''It could be''', 'true', 'Avoids direct answers with vague qualifiers', 'Ask for specificity gently. ''If you had to choose one — which feels most true?''', '1', 'Deflection hedging', 'Psychological State Scoring Table — Acute State Detection', 'B', 'Withdrawal / Shutdown', '5 points in one response') on conflict do nothing;
insert into "psychological_state_signals" ("signal_id", "created_at", "example_phrases", "is_active", "observable_indicator", "protocol_adjustment", "score_per_instance", "signal_type", "source_document", "state_code", "state_name", "trigger_threshold") values ('8', '2026-07-26 05:12:17.653652+00', '''Yes,'' ''Exactly,'' ''Right,'' repeated without elaboration', 'true', 'Agrees with everything without engagement', 'Break the pattern. ''Tell me something that is not going well — what is the hardest thing right now?''', '2', 'Flat affirmatives', 'Psychological State Scoring Table — Acute State Detection', 'B', 'Withdrawal / Shutdown', '6 points across 3 responses') on conflict do nothing;
insert into "psychological_state_signals" ("signal_id", "created_at", "example_phrases", "is_active", "observable_indicator", "protocol_adjustment", "score_per_instance", "signal_type", "source_document", "state_code", "state_name", "trigger_threshold") values ('9', '2026-07-26 05:12:17.653652+00', '''Mistakes were made,'' ''Things did not go as planned,'' ''The team decided''', 'true', 'Removes self from events', 'Bring the founder back in. ''When you say the team decided — what was your role in that?''', '3', 'Passive voice / third-person deflection', 'Psychological State Scoring Table — Acute State Detection', 'B', 'Withdrawal / Shutdown', '3 points in one response') on conflict do nothing;
insert into "psychological_state_signals" ("signal_id", "created_at", "example_phrases", "is_active", "observable_indicator", "protocol_adjustment", "score_per_instance", "signal_type", "source_document", "state_code", "state_name", "trigger_threshold") values ('10', '2026-07-26 05:12:17.653652+00', '''It is fine,'' ''We will figure it out,'' ''Not a big deal'' repeated 3+ times', 'true', 'Identical reassuring phrases across multiple answers', 'Name it without confronting it. ''You have said it is fine a few times — I want to make sure I am not missing something important.''', '2', 'Repeated reassurance phrases', 'Psychological State Scoring Table — Acute State Detection', 'B', 'Withdrawal / Shutdown', '6 points across session') on conflict do nothing;
insert into "psychological_state_signals" ("signal_id", "created_at", "example_phrases", "is_active", "observable_indicator", "protocol_adjustment", "score_per_instance", "signal_type", "source_document", "state_code", "state_name", "trigger_threshold") values ('11', '2026-07-26 05:12:17.653652+00', '''This is incredible,'' ''We are absolutely going to crush it,'' ''Revolutionary product''', 'true', 'Excessive optimism and enthusiasm about uncertain outcomes', 'Test the optimism gently. ''That sounds exciting. What is the one thing that could go wrong that worries you most?''', '2', 'Positive superlative overuse', 'Psychological State Scoring Table — Acute State Detection', 'C', 'Defensiveness / Performance Mode', '8 points in session') on conflict do nothing;
insert into "psychological_state_signals" ("signal_id", "created_at", "example_phrases", "is_active", "observable_indicator", "protocol_adjustment", "score_per_instance", "signal_type", "source_document", "state_code", "state_name", "trigger_threshold") values ('12', '2026-07-26 05:12:17.653652+00', '''We actually learned so much from that failure,'' ''It was a blessing in disguise''', 'true', 'Proactively spins setbacks before being asked', 'Acknowledge the reframe, then go deeper. ''That is a healthy perspective. What did it actually feel like in the moment it happened?''', '3', 'Reframing failures as lessons unprompted', 'Psychological State Scoring Table — Acute State Detection', 'C', 'Defensiveness / Performance Mode', '3 points in one response') on conflict do nothing;
insert into "psychological_state_signals" ("signal_id", "created_at", "example_phrases", "is_active", "observable_indicator", "protocol_adjustment", "score_per_instance", "signal_type", "source_document", "state_code", "state_name", "trigger_threshold") values ('13', '2026-07-26 05:12:17.653652+00', '''We won X award,'' ''We were covered in Forbes,'' ''Our investors include...''', 'true', 'Leads with credentials, logos, or social proof before answering diagnostic questions', 'Validate, then redirect. ''That is great context. Tell me more about what the business looks like day to day.''', '2', 'Credential leading', 'Psychological State Scoring Table — Acute State Detection', 'C', 'Defensiveness / Performance Mode', '6 points in session') on conflict do nothing;
insert into "psychological_state_signals" ("signal_id", "created_at", "example_phrases", "is_active", "observable_indicator", "protocol_adjustment", "score_per_instance", "signal_type", "source_document", "state_code", "state_name", "trigger_threshold") values ('14', '2026-07-26 05:12:17.653652+00', 'Question about sales pipeline → answer about product vision', 'true', 'Consistently answers the question they wish they were asked, not the one asked', 'Name it kindly. ''I want to make sure I understood — specifically about the pipeline, how many active conversations do you have right now?''', '3', 'Answering different question', 'Psychological State Scoring Table — Acute State Detection', 'C', 'Defensiveness / Performance Mode', '3 points across 3 responses') on conflict do nothing;
insert into "psychological_state_signals" ("signal_id", "created_at", "example_phrases", "is_active", "observable_indicator", "protocol_adjustment", "score_per_instance", "signal_type", "source_document", "state_code", "state_name", "trigger_threshold") values ('15', '2026-07-26 05:12:17.653652+00', '''Our advisor who was ex-Google said...'' / ''Sequoia told us...''', 'true', 'Mentions high-profile advisors or networks to establish credibility under pressure', 'Accept it without dwelling. Return to the diagnostic question without further attention to the credential.', '2', 'Advisor dropping', 'Psychological State Scoring Table — Acute State Detection', 'C', 'Defensiveness / Performance Mode', '6 points in session') on conflict do nothing;
insert into "psychological_state_signals" ("signal_id", "created_at", "example_phrases", "is_active", "observable_indicator", "protocol_adjustment", "score_per_instance", "signal_type", "source_document", "state_code", "state_name", "trigger_threshold") values ('16', '2026-07-26 05:12:17.653652+00', '''I am a failure,'' ''I cannot do this,'' ''I was not meant for this''', 'true', 'Conflates personal failure with business failure', 'STOP the diagnostic. Shift fully to empathetic listening. ''That sounds incredibly hard. Can you tell me more about how you are feeling?''', '5', 'Identity collapse language', 'Psychological State Scoring Table — Acute State Detection', 'D', 'Emotional Distress / Crisis Signals', '5 points (single instance)') on conflict do nothing;
insert into "psychological_state_signals" ("signal_id", "created_at", "example_phrases", "is_active", "observable_indicator", "protocol_adjustment", "score_per_instance", "signal_type", "source_document", "state_code", "state_name", "trigger_threshold") values ('17', '2026-07-26 05:12:17.653652+00', '''Nothing will work,'' ''I have tried everything,'' ''It is pointless''', 'true', 'Expresses no belief that anything can improve', 'STOP the diagnostic. Acknowledge. ''I hear you. This sounds really overwhelming. You do not have to have all the answers right now.''', '5', 'Helplessness / hopelessness language', 'Psychological State Scoring Table — Acute State Detection', 'D', 'Emotional Distress / Crisis Signals', '5 points (single instance)') on conflict do nothing;
insert into "psychological_state_signals" ("signal_id", "created_at", "example_phrases", "is_active", "observable_indicator", "protocol_adjustment", "score_per_instance", "signal_type", "source_document", "state_code", "state_name", "trigger_threshold") values ('18', '2026-07-26 05:12:17.653652+00', '''No one understands,'' ''I cannot tell anyone,'' ''I am completely alone in this''', 'true', 'Expresses being completely alone with the problem', 'Normalise and gently connect. ''Many founders feel this way and it is one of the hardest parts. Do you have anyone you trust outside the business?''', '4', 'Isolation language', 'Psychological State Scoring Table — Acute State Detection', 'D', 'Emotional Distress / Crisis Signals', '4 points (single instance)') on conflict do nothing;
insert into "psychological_state_signals" ("signal_id", "created_at", "example_phrases", "is_active", "observable_indicator", "protocol_adjustment", "score_per_instance", "signal_type", "source_document", "state_code", "state_name", "trigger_threshold") values ('19', '2026-07-26 05:12:17.653652+00', '''I have not slept properly in weeks,'' ''I cannot remember the last time I ate a proper meal''', 'true', 'Reveals extended period of physical neglect', 'Acknowledge physical state before continuing. ''Before we go further — how long has it been like this? Your capacity to think clearly matters here.''', '3', 'Mentions of sleep deprivation or health neglect', 'Psychological State Scoring Table — Acute State Detection', 'D', 'Emotional Distress / Crisis Signals', '3 points (single instance)') on conflict do nothing;
insert into "psychological_state_signals" ("signal_id", "created_at", "example_phrases", "is_active", "observable_indicator", "protocol_adjustment", "score_per_instance", "signal_type", "source_document", "state_code", "state_name", "trigger_threshold") values ('20', '2026-07-26 05:12:17.653652+00', '''We are going to fail,'' ''This is over,'' ''There is no way out''', 'true', 'States extremely negative outcomes as definite facts', 'STOP the diagnostic. Acknowledge without agreeing or disagreeing. Do not offer solutions. Ask one question: ''What would need to be true for things to feel even slightly more manageable?''', '5', 'Catastrophic certainty', 'Psychological State Scoring Table — Acute State Detection', 'D', 'Emotional Distress / Crisis Signals', '5 points (single instance)') on conflict do nothing;
